#include "game_math.h"

/* Bias negative values before arithmetic shift; callers use shifts below32 */
sint32 mips_div_pow2_trunc(sint32 val, uint32 shift)
{
    if (val < 0)
        val += ((1u << shift) - 1u);
    return val >> shift;
}

/* Preserve the original low-word negation for INT_MIN as well */
sint32 abs_s32(sint32 val)
{
    return val < 0 ? -(uint32)val : val;
}

/* Original: FUN_800ACF98. */
sint16 angle_approach_wrapped(sint16 target, sint32 step, sint16 cur)
{
    sint32 distance = abs_s32(target - cur);
    uint32 move = 0;
    /* Comparison narrows both operands, but selection retains the full step */
    if ((sint16)distance > (sint16)step)
        distance = step;
    if (cur != target)
    {
        move = target < cur ? (-(uint32)distance) : distance;
        if (abs_s32(cur - target) >= 0x801)
            move = (-move);
    }
    return ((cur + move) & 0xfffu);
}

/* Positions and steps carry eight fractional bits; shifts retain the low word */
/* Original: FUN_8009EE30. */
sint32 fixed_dda_initialize(sint32 x0, sint32 y0, sint32 z0, sint32 x1, sint32 y1, sint32 z1, FIXED_DDA_LINE *line)
{
    sint32 px = (uint32)x0 << 8;
    sint32 py = (uint32)y0 << 8;
    sint32 pz = (uint32)z0 << 8;
    sint32 dx = ((uint32)x1 << 8) - px;
    sint32 dy = ((uint32)y1 << 8) - py;
    sint32 dz = ((uint32)z1 << 8) - pz;
    sint32 steps = div_256_trunc(abs_s32(dx));
    sint32 sx = 0, sy = 0, sz = 0;
    sint32 axis_steps;

    if (dx != 0)
    {
        sx = dx < 0 ? -0x10000 : 0x10000;
        sy = ((uint32)(dy / steps) << 8);
        sz = ((uint32)(dz / steps) << 8);
    }
    if (dy != 0)
    {
        axis_steps = div_256_trunc(abs_s32(dy));
        if (axis_steps > steps)
        {
            steps = axis_steps;
            sy = dy < 0 ? -0x10000 : 0x10000;
            sx = ((uint32)(dx / steps) << 8);
            sz = ((uint32)(dz / steps) << 8);
        }
    }
    if (dz != 0)
    {
        axis_steps = div_256_trunc(abs_s32(dz));
        if (axis_steps > steps)
        {
            steps = axis_steps;
            sz = dz < 0 ? -0x10000 : 0x10000;
            sx = ((uint32)(dx / steps) << 8);
            sy = ((uint32)(dy / steps) << 8);
        }
    }
    line->step.x = sx;
    line->step.y = sy;
    line->step.z = sz;
    line->pos.x = px;
    line->pos.y = py;
    line->pos.z = pz;
    return steps;
}

/* Original: FUN_8009F07C. */
void fixed_dda_advance(FIXED_DDA_LINE *line)
{
    line->pos.x = ((uint32)line->pos.x + line->step.x);
    line->pos.y = ((uint32)line->pos.y + line->step.y);
    line->pos.z = ((uint32)line->pos.z + line->step.z);
}

