/* Original: FUN_800A4DC0. */
sint32 fixed_angle_from_vector(sint32 x, sint32 z)
{
    sint32 ax = abs_s32(x);
    sint32 az = abs_s32(z);
    sint32 angle;
    angle = g_vector_angles[az & 0x3f][ax & 0x3f];
    if (z < 0)
        angle = 0x200 - angle;
    if (x < 0)
        angle = 0x400 - angle;
    return angle;
}
